UPDATE pf.mcp_probe_outbox SET state='PUBLISHED',relay_owner=NULL,relay_until=NULL
  WHERE id=#{publication.id} AND space_id=#{publication.spaceId} AND probe_id=#{publication.probeId}
   AND generation=#{publication.generation} AND state='PUBLISHING' AND relay_owner=#{publication.relayOwner}

mapper.select:
SELECT  FROM pf.mcp_probe p JOIN pf.mcp_probe_outbox o
  ON o.probe_id=p.id AND o.space_id=p.space_id AND o.generation=p.generation WHERE o.id=#{publication.id}
  AND o.space_id=#{publication.spaceId} AND o.probe_id=#{publication.probeId} AND o.generation=#{publication.generation} FOR UPDATE OF p

SELECT  FROM pf.mcp_probe p
  WHERE p.id=#{command.probeId} AND p.space_id=#{command.spaceId} AND p.owner_user_id=#{command.actorId} AND p.capability_id=#{command.connectorId}
   AND p.configuration_revision=#{command.configurationRevision} AND p.owner_id=#{command.ownerId} AND p.generation=#{command.generation}
   AND p.fence=#{command.fence} AND p.policy_hash=#{command.policyHash} AND p.state='RUNNING' AND p.lease_until>clock_timestamp() FOR UPDATE OF p

SELECT EXISTS(SELECT 1 FROM pf.mcp_connector_configuration c
  WHERE c.space_id=#{row.spaceId} AND c.owner_user_id=#{row.ownerUserId} AND c.capability_id=#{row.capabilityId} AND c.revision=#{row.configurationRevision}
   AND c.endpoint=#{row.endpoint} AND c.auth_kind=#{row.authKind} AND c.api_key_header IS NOT DISTINCT FROM #{row.apiKeyHeader,jdbcType=VARCHAR}
   AND c.credential_id IS NOT DISTINCT FROM #{row.credentialId,jdbcType=OTHER} AND c.credential_revision IS NOT DISTINCT FROM #{row.credentialRevision,jdbcType=BIGINT} FOR SHARE)

