UPDATE pf.mcp_probe SET lease_until=clock_timestamp()+interval '60 seconds' WHERE id=#{command.probeId}
  AND space_id=#{command.spaceId} AND owner_user_id=#{command.actorId} AND state='RUNNING' AND owner_id=#{command.ownerId}
  AND generation=#{command.generation} AND fence=#{command.fence} AND policy_hash=#{command.policyHash} AND lease_until>clock_timestamp()

UPDATE pf.mcp_probe SET state=#{state},error_code=#{reason},owner_id=NULL,fence=NULL,lease_until=NULL,revision=revision+1 WHERE id=#{command.probeId}
  AND space_id=#{command.spaceId} AND owner_user_id=#{command.actorId} AND state='RUNNING' AND owner_id=#{command.ownerId}
  AND generation=#{command.generation} AND fence=#{command.fence} AND policy_hash=#{command.policyHash} AND lease_until>clock_timestamp()

UPDATE pf.mcp_probe SET state='READY',result_version_id=#{version},owner_id=NULL,fence=NULL,lease_until=NULL,revision=revision+1
  WHERE id=#{command.probeId} AND space_id=#{command.spaceId} AND state='RUNNING' AND owner_id=#{command.ownerId}
  AND generation=#{command.generation} AND fence=#{command.fence} AND policy_hash=#{command.policyHash} AND lease_until>clock_timestamp()
